#!/usr/bin/env Rscript

# ==============================================================================
# 01_heatmap_interaction_FDR005_perCluster_oneHeatmap_FIXED3.R
#
# One heatmap for significant Group x Sex interaction results from the
# cluster-specific pseudobulk edgeR analysis.
#
# IMPORTANT
#   This version reads everything from the two RData files generated by the
#   edgeR workflow:
#
#   1. *_edgeRResults.RData
#      - edgeR_perCluster_combinedResults
#      - edgeR_perCluster_testDefinitions
#
#   2. *_edgeRModelObjects.RData
#      - edgeR_perCluster_modelObjects
#      - DGEList for every completed cluster
#      - sample metadata and TMM normalization factors
#
#   It does NOT search for separate sample-level metadata TSV files.
#
# ROWS
#   Significant cluster-gene interaction results at FDR < 0.05.
#   The same gene can occur more than once when significant in several clusters.
#
# COLUMNS
#   Samples ordered as:
#     Male Neurotypical -> Male ASD -> Female Neurotypical -> Female ASD
#
# HEATMAP VALUES
#   TMM-normalized CPM per sample and cluster
#   -> log2(CPM + 1)
#   -> row-wise Z-score
#   -> clipped to [-2, 2]
#
# ROW ORGANIZATION
#   Rows are split first by source cluster and then by interaction logFC sign.
#   Genes are hierarchically clustered separately inside every resulting block.
#
# ROW ANNOTATIONS
#   - source cluster, using manual-clustering colours;
#   - maximum mean percent-positive spots across the four Sex x Group cells;
#   - interaction logFC direction.
# ==============================================================================

options(stringsAsFactors = FALSE)


