find_interaction_test_id <- function(test_definitions) {

  required_columns <- c(
    "test_id",
    "sheet_name",
    "comparison"
  )

  missing_columns <- setdiff(
    required_columns,
    colnames(test_definitions)
  )

  if (length(missing_columns) > 0L) {
    stop(
      "Test-definition table is missing: ",
      paste(missing_columns, collapse = ", "),
      call. = FALSE
    )
  }

  candidate_rows <- test_definitions |>
    dplyr::filter(
      grepl("interaction", .data$test_id, ignore.case = TRUE) |
        grepl("interaction", .data$sheet_name, ignore.case = TRUE) |
        grepl("interaction", .data$comparison, ignore.case = TRUE)
    )

  if (nrow(candidate_rows) != 1L) {
    stop(
      "Could not uniquely identify the interaction test. Candidates found: ",
      nrow(candidate_rows),
      call. = FALSE
    )
  }

  as.character(candidate_rows$test_id[[1]])
}


calculate_row_zscores <- function(
    expression_matrix,
    lower_limit = -2,
    upper_limit = 2
) {

  output_matrix <- matrix(
    NA_real_,
    nrow = nrow(expression_matrix),
    ncol = ncol(expression_matrix),
    dimnames = dimnames(expression_matrix)
  )

  for (row_index in seq_len(nrow(expression_matrix))) {

    values <- as.numeric(expression_matrix[row_index, ])
    finite_values <- is.finite(values)

    if (sum(finite_values) < 2L) {
      output_matrix[row_index, finite_values] <- 0
      next
    }

    row_mean <- mean(values[finite_values])
    row_sd <- stats::sd(values[finite_values])

    if (!is.finite(row_sd) || row_sd == 0) {
      output_matrix[row_index, finite_values] <- 0
      next
    }

    output_matrix[row_index, finite_values] <-
      (values[finite_values] - row_mean) / row_sd
  }

  output_matrix[
    is.finite(output_matrix) & output_matrix < lower_limit
  ] <- lower_limit

  output_matrix[
    is.finite(output_matrix) & output_matrix > upper_limit
  ] <- upper_limit

  output_matrix
}


impute_cpm_by_group_mean <- function(
    cpm_matrix,
    sample_metadata,
    fallback_to_row_mean = TRUE
) {

  required_metadata_columns <- c(
    "sample_ID",
    "combined_group"
  )

  missing_metadata_columns <- setdiff(
    required_metadata_columns,
    colnames(sample_metadata)
  )

  if (length(missing_metadata_columns) > 0L) {
    stop(
      "Sample metadata is missing columns required for imputation: ",
      paste(missing_metadata_columns, collapse = ", "),
      call. = FALSE
    )
  }

  metadata_aligned <- sample_metadata[
    match(colnames(cpm_matrix), sample_metadata$sample_ID),
    ,
    drop = FALSE
  ]

  if (anyNA(metadata_aligned$sample_ID)) {
    stop(
      "Could not align sample metadata to CPM matrix columns for imputation.",
      call. = FALSE
    )
  }

  group_labels <- as.character(metadata_aligned$combined_group)

  if (anyNA(group_labels)) {
    stop(
      "Combined Sex x FMT donor-group labels contain NA values.",
      call. = FALSE
    )
  }

  imputed_matrix <- cpm_matrix
  imputation_mask <- matrix(
    FALSE,
    nrow = nrow(cpm_matrix),
    ncol = ncol(cpm_matrix),
    dimnames = dimnames(cpm_matrix)
  )

  for (row_index in seq_len(nrow(imputed_matrix))) {

    for (group_current in unique(group_labels)) {

      group_columns <- which(group_labels == group_current)
      group_values <- imputed_matrix[row_index, group_columns]

      missing_in_group <- is.na(group_values)
      observed_in_group <- is.finite(group_values)

      if (any(missing_in_group) && any(observed_in_group)) {
        group_mean <- mean(
          group_values[observed_in_group],
          na.rm = TRUE
        )

        target_columns <- group_columns[missing_in_group]
        imputed_matrix[row_index, target_columns] <- group_mean
        imputation_mask[row_index, target_columns] <- TRUE
      }
    }

    remaining_missing <- which(is.na(imputed_matrix[row_index, ]))

    if (
      length(remaining_missing) > 0L &&
        isTRUE(fallback_to_row_mean)
    ) {
      observed_row_values <- imputed_matrix[
        row_index,
        is.finite(imputed_matrix[row_index, ])
      ]

      if (length(observed_row_values) > 0L) {
        row_mean <- mean(observed_row_values)
        imputed_matrix[row_index, remaining_missing] <- row_mean
        imputation_mask[row_index, remaining_missing] <- TRUE
      }
    }
  }

  remaining_missing_count <- sum(is.na(imputed_matrix))

  if (remaining_missing_count > 0L) {
    stop(
      "Imputation left ",
      remaining_missing_count,
      " missing CPM value(s).",
      call. = FALSE
    )
  }

  list(
    matrix = imputed_matrix,
    mask = imputation_mask,
    number_imputed = sum(imputation_mask),
    number_rows_with_imputation = sum(rowSums(imputation_mask) > 0L)
  )
}


modified_correlation_distance <- function(
    expression_matrix,
    cluster_labels,
    base_distance = "2 - r",
    r_scale = 1,
    same_cluster_bonus = 0.25
) {

  if (!is.matrix(expression_matrix)) {
    expression_matrix <- as.matrix(expression_matrix)
  }

  if (nrow(expression_matrix) <= 1L) {
    return(stats::as.dist(matrix(0, nrow = 1, ncol = 1)))
  }

  cluster_labels <- as.character(cluster_labels)

  if (length(cluster_labels) != nrow(expression_matrix)) {
    stop(
      "The number of cluster labels must equal the number of heatmap rows.",
      call. = FALSE
    )
  }

  if (!is.numeric(r_scale) || length(r_scale) != 1L || !is.finite(r_scale)) {
    stop("`r_scale` must be one finite numeric value.", call. = FALSE)
  }

  if (
    !is.numeric(same_cluster_bonus) ||
      length(same_cluster_bonus) != 1L ||
      !is.finite(same_cluster_bonus) ||
      same_cluster_bonus < 0 ||
      same_cluster_bonus >= 1
  ) {
    stop(
      "`same_cluster_bonus` must be a finite number in [0, 1).",
      call. = FALSE
    )
  }

  cor_mat <- suppressWarnings(
    stats::cor(
      t(expression_matrix),
      method = "pearson",
      use = "pairwise.complete.obs"
    )
  )

  cor_mat[!is.finite(cor_mat)] <- 0
  diag(cor_mat) <- 1

  base_dist <- if (identical(base_distance, "2 - r")) {
    2 - (cor_mat * r_scale)
  } else if (identical(base_distance, "1 - r")) {
    1 - (cor_mat * r_scale)
  } else {
    stop(
      "`base_distance` must be either '2 - r' or '1 - r'.",
      call. = FALSE
    )
  }

  same_cluster_matrix <- outer(
    cluster_labels,
    cluster_labels,
    FUN = "=="
  )

  dist_mat <- base_dist

  dist_mat[same_cluster_matrix] <-
    base_dist[same_cluster_matrix] * (1 - same_cluster_bonus)

  dist_mat[!same_cluster_matrix] <-
    base_dist[!same_cluster_matrix] * (1 + same_cluster_bonus)

  diag(dist_mat) <- 0
  dist_mat[dist_mat < 0] <- 0

  stats::as.dist(dist_mat)
}


create_modified_row_hclust <- function(
    expression_matrix,
    annotation_table,
    base_distance = "2 - r",
    r_scale = 1,
    same_cluster_bonus = 0.25,
    linkage_method = "complete"
) {

  matched_annotation <- annotation_table[
    match(rownames(expression_matrix), annotation_table$row_id),
    ,
    drop = FALSE
  ]

  if (
    nrow(matched_annotation) != nrow(expression_matrix) ||
      anyNA(matched_annotation$row_id) ||
      anyNA(matched_annotation$cluster_id)
  ) {
    stop(
      "Failed to match source-cluster annotations to all heatmap rows.",
      call. = FALSE
    )
  }

  modified_distance <- modified_correlation_distance(
    expression_matrix = expression_matrix,
    cluster_labels = matched_annotation$cluster_id,
    base_distance = base_distance,
    r_scale = r_scale,
    same_cluster_bonus = same_cluster_bonus
  )

  stats::hclust(
    modified_distance,
    method = linkage_method
  )
}


