# 9. Extract sample metadata directly from DGEList objects
# ==============================================================================

sample_metadata_list <- lapply(
  significant_cluster_ids,
  function(cluster_id_current) {

    model_object <-
      edgeR_perCluster_modelObjects[[cluster_id_current]]

    if (is.null(model_object$dge)) {
      stop(
        "DGEList is missing for cluster ",
        cluster_id_current,
        call. = FALSE
      )
    }

    dge_samples <- model_object$dge$samples |>
      tibble::rownames_to_column("dge_rowname") |>
      tibble::as_tibble()

    required_dge_sample_columns <- c(
      "sample_ID",
      "fmt_donor_group",
      "sex"
    )

    missing_dge_sample_columns <- setdiff(
      required_dge_sample_columns,
      colnames(dge_samples)
    )

    if (length(missing_dge_sample_columns) > 0L) {
      stop(
        "DGEList sample metadata for cluster ",
        cluster_id_current,
        " is missing: ",
        paste(missing_dge_sample_columns, collapse = ", "),
        call. = FALSE
      )
    }

    dge_samples |>
      dplyr::transmute(
        sample_ID = as.character(.data$sample_ID),
        fmt_donor_group = as.character(.data$fmt_donor_group),
        sex = as.character(.data$sex)
      )
  }
)

sample_metadata <- sample_metadata_list |>
  dplyr::bind_rows() |>
  dplyr::distinct(
    .data$sample_ID,
    .data$fmt_donor_group,
    .data$sex
  )

metadata_conflicts <- sample_metadata |>
  dplyr::count(.data$sample_ID, name = "n_metadata_rows") |>
  dplyr::filter(.data$n_metadata_rows > 1L)

if (nrow(metadata_conflicts) > 0L) {
  stop(
    "Conflicting Sex/Group metadata found for sample(s): ",
    paste(metadata_conflicts$sample_ID, collapse = ", "),
    call. = FALSE
  )
}

sample_metadata <- sample_metadata |>
  dplyr::mutate(
    sex = factor(
      .data$sex,
      levels = c("Male", "Female")
    ),
    fmt_donor_group = factor(
      .data$fmt_donor_group,
      levels = c("Neurotypical", "ASD")
    )
  )

if (anyNA(sample_metadata$sex)) {
  stop("Unexpected sex value in DGEList metadata.", call. = FALSE)
}

if (anyNA(sample_metadata$fmt_donor_group)) {
  stop(
    "Unexpected fmt_donor_group value in DGEList metadata.",
    call. = FALSE
  )
}

sample_metadata <- sample_metadata |>
  dplyr::arrange(
    .data$sex,
    .data$fmt_donor_group,
    .data$sample_ID
  ) |>
  dplyr::mutate(
    sample_order = dplyr::row_number(),
    combined_group = factor(
      paste(
        as.character(.data$sex),
        as.character(.data$fmt_donor_group),
        sep = "_"
      ),
      levels = c(
        "Male_Neurotypical",
        "Male_ASD",
        "Female_Neurotypical",
        "Female_ASD"
      )
    )
  )

sample_order <- as.character(sample_metadata$sample_ID)

message("\nSample order used in the heatmap:")
print(
  sample_metadata |>
    dplyr::select(
      .data$sample_order,
      .data$sample_ID,
      .data$sex,
      .data$fmt_donor_group,
      .data$combined_group
    ),
  n = Inf
)


# ==============================================================================
# 10. Calculate sample-level TMM-CPM directly from every cluster DGEList
# ==============================================================================

cluster_cpm_matrices <- lapply(
  significant_cluster_ids,
  function(cluster_id_current) {

    dge <-
      edgeR_perCluster_modelObjects[[cluster_id_current]]$dge

    cpm_matrix <- edgeR::cpm(
      dge,
      normalized.lib.sizes = TRUE,
      log = FALSE
    )

    if (is.null(rownames(cpm_matrix))) {
      stop(
        "TMM-CPM matrix has no gene IDs for cluster ",
        cluster_id_current,
        call. = FALSE
      )
    }

    if (is.null(colnames(cpm_matrix))) {
      stop(
        "TMM-CPM matrix has no sample IDs for cluster ",
        cluster_id_current,
        call. = FALSE
      )
    }

    cpm_matrix
  }
)

names(cluster_cpm_matrices) <- significant_cluster_ids


# ==============================================================================
# 11. Build one cluster-gene x sample CPM matrix
# ==============================================================================

sample_level_cpm_matrix <- matrix(
  NA_real_,
  nrow = nrow(significant_interaction),
  ncol = length(sample_order),
  dimnames = list(
    NULL,
    sample_order
  )
)

row_ids <- paste0(
  ifelse(
    is.na(significant_interaction$gene) |
      significant_interaction$gene == "",
    significant_interaction$ensembl_gene_id,
    significant_interaction$gene
  ),
  " [C",
  significant_interaction$cluster_id,
  "]"
)

# The cluster tag makes repeated gene symbols unambiguous without changing
# the official gene symbol itself, e.g. Ttr [C14] versus Ttr [C15].
if (anyDuplicated(row_ids) > 0L) {
  duplicated_labels <- unique(row_ids[duplicated(row_ids)])
  stop(
    "Duplicated gene-cluster row labels detected: ",
    paste(duplicated_labels, collapse = ", "),
    call. = FALSE
  )
}
rownames(sample_level_cpm_matrix) <- row_ids

for (row_index in seq_len(nrow(significant_interaction))) {

  current_cluster <-
    significant_interaction$cluster_id[[row_index]]

  current_gene_id <-
    significant_interaction$ensembl_gene_id[[row_index]]

  current_cpm_matrix <-
    cluster_cpm_matrices[[current_cluster]]

  gene_match <- match(
    current_gene_id,
    rownames(current_cpm_matrix)
  )

  if (is.na(gene_match)) {
    stop(
      "Gene ",
      current_gene_id,
      " is missing from the tested DGEList genes for cluster ",
      current_cluster,
      call. = FALSE
    )
  }

  available_samples <- intersect(
    sample_order,
    colnames(current_cpm_matrix)
  )

  sample_level_cpm_matrix[
    row_index,
    available_samples
  ] <- current_cpm_matrix[
    gene_match,
    available_samples,
    drop = TRUE
  ]
}

if (all(is.na(sample_level_cpm_matrix))) {
  stop(
    "The complete cluster-gene CPM matrix contains only NA values.",
    call. = FALSE
  )
}

number_missing_before_imputation <- sum(is.na(sample_level_cpm_matrix))
number_imputed_values <- 0L
number_rows_with_imputation <- 0L

if (isTRUE(impute_missing_by_group_mean)) {

  imputation_output <- impute_cpm_by_group_mean(
    cpm_matrix = sample_level_cpm_matrix,
    sample_metadata = sample_metadata,
    fallback_to_row_mean = imputation_fallback_to_row_mean
  )

  sample_level_cpm_matrix <- imputation_output$matrix
  imputation_mask <- imputation_output$mask
  number_imputed_values <- imputation_output$number_imputed
  number_rows_with_imputation <-
    imputation_output$number_rows_with_imputation

  message(
    "Missing sample-cluster CPM values before imputation: ",
    number_missing_before_imputation
  )
  message(
    "CPM values imputed by within-group mean: ",
    number_imputed_values
  )
  message(
    "Heatmap rows containing at least one imputed value: ",
    number_rows_with_imputation
  )

} else {

  imputation_mask <- matrix(
    FALSE,
    nrow = nrow(sample_level_cpm_matrix),
    ncol = ncol(sample_level_cpm_matrix),
    dimnames = dimnames(sample_level_cpm_matrix)
  )
}


# ==============================================================================
# 12. Transformation for visualization
# ==============================================================================

log2_cpm_matrix <- log2(sample_level_cpm_matrix + 1)

zscore_matrix <- calculate_row_zscores(
  expression_matrix = log2_cpm_matrix,
  lower_limit = zscore_lower_limit,
  upper_limit = zscore_upper_limit
)


# ==============================================================================
# 13. Row annotations
# ==============================================================================

row_annotation_table <- significant_interaction |>
  dplyr::transmute(
    row_id = row_ids,
    cluster_id = .data$cluster_id,
    cluster_label = vapply(
      .data$cluster_id,
      format_cluster_label,
      FUN.VALUE = character(1)
    ),
    interaction_direction = .data$interaction_direction,
    logFC = .data$logFC,
    PValue = .data$PValue,
    FDR = .data$FDR,
    max_mean_percent = .data$max_mean_percent
  )

cluster_factor_levels <- as.character(significant_clusters)

cluster_annotation_colors <- custom_cluster_colors[
  cluster_factor_levels
]

names(cluster_annotation_colors) <- cluster_factor_levels

max_mean_percent_color_function <- circlize::colorRamp2(
  c(0, 25, 50, 75, 100),
  c(
    "#F3E8FF",
    "#DDD6FE",
    "#C084FC",
    "#9333EA",
    "#4C1D95"
  )
)

right_annotation <- ComplexHeatmap::rowAnnotation(
  Cluster = row_annotation_table$cluster_id,
  `Max mean %` = row_annotation_table$max_mean_percent,
  col = list(
    Cluster = cluster_annotation_colors,
    `Max mean %` = max_mean_percent_color_function
  ),
  simple_anno_size = grid::unit(4.2, "mm"),
  annotation_name_gp = grid::gpar(
    fontsize = 9,
    fontface = "bold"
  ),
  annotation_legend_param = list(
    Cluster = list(
      title = "Source cluster",
      labels = paste0(
        "C",
        cluster_factor_levels,
        " | ",
        unname(custom_cluster_labels[cluster_factor_levels])
      ),
      at = cluster_factor_levels,
      ncol = 1
    ),
    `Max mean %` = list(
      title = "Maximum mean\npositive\nspots (%)",
      at = c(0, 25, 50, 75, 100)
    )
  )
)


# One global row clustering and one dendrogram.
# The source cluster modifies pairwise distances but does not impose a hard split.
hc_rows <- create_modified_row_hclust(
  expression_matrix = zscore_matrix,
  annotation_table = row_annotation_table,
  base_distance = row_clustering_base_distance,
  r_scale = row_clustering_r_scale,
  same_cluster_bonus = row_clustering_same_cluster_bonus,
  linkage_method = row_clustering_linkage_method
)


# ==============================================================================
# 14. Column annotation
# ==============================================================================

sex_colors <- c(
  "Male" = "#3C78D8",
  "Female" = "#C050A0"
)

group_colors <- c(
  "Neurotypical" = "grey70",
  "ASD" = "black"
)

top_annotation <- ComplexHeatmap::HeatmapAnnotation(
  Group = sample_metadata$fmt_donor_group,
  Sex = sample_metadata$sex,
  col = list(
    Group = group_colors,
    Sex = sex_colors
  ),
  simple_anno_size = grid::unit(4.2, "mm"),
  annotation_name_side = "left",
  annotation_name_gp = grid::gpar(
    fontsize = 9,
    fontface = "bold"
  ),
  annotation_legend_param = list(
    Group = list(
      title = "FMT donor group",
      ncol = 1
    ),
    Sex = list(
      title = "Sex",
      ncol = 1
    )
  )
)


# ==============================================================================
# 15. Heatmap title and dimensions
# ==============================================================================

number_of_results <- nrow(significant_interaction)
number_of_unique_genes <- length(unique(significant_interaction$gene))
number_of_clusters <- length(significant_cluster_ids)
number_of_samples <- ncol(zscore_matrix)

heatmap_title_lines <- c(
  "Group x Sex interaction: significant genes per cluster",
  paste0(
    "Selection: FDR < ",
    fdr_threshold,
    " | ",
    number_of_results,
    " cluster-gene results | ",
    number_of_unique_genes,
    " unique genes | ",
    number_of_clusters,
    " clusters"
  ),
  "Input: sample-level TMM-normalized CPM from each cluster DGEList",
  "Transformation: log2(CPM + 1) -> row Z-score clipped to [-2, 2]",
  if (isTRUE(impute_missing_by_group_mean)) {
    paste0(
      "Missing sample-cluster CPM: imputed by mean within Sex x FMT donor group before log2",
      " | imputed values: ",
      number_imputed_values
    )
  } else {
    "Missing sample-cluster CPM retained as NA (shown in grey)"
  },
  paste0(
    "Columns: Male Neurotypical -> Male ASD -> Female Neurotypical -> Female ASD",
    " | ",
    number_of_samples,
    " samples"
  ),
  paste0(
    "Row clustering: Pearson correlation on row Z-scores",
    " | base distance d = ",
    row_clustering_base_distance,
    " | r_scale = ",
    row_clustering_r_scale
  ),
  paste0(
    "Same-cluster bonus = ",
    row_clustering_same_cluster_bonus,
    " -> same cluster: d x ",
    formatC(1 - row_clustering_same_cluster_bonus, format = "f", digits = 2),
    ", different clusters: d x ",
    formatC(1 + row_clustering_same_cluster_bonus, format = "f", digits = 2),
    " | linkage = ",
    row_clustering_linkage_method
  ),
  clustering_title
)

heatmap_title <- paste(
  heatmap_title_lines,
  collapse = "\n"
)

row_font_size <- if (number_of_results <= 80L) {
  7.2
} else if (number_of_results <= 180L) {
  5.8
} else {
  4.8
}

row_height_mm <- if (number_of_results <= 80L) {
  3.1
} else if (number_of_results <= 180L) {
  2.35
} else {
  1.9
}

heatmap_body_height_mm <- number_of_results * row_height_mm
heatmap_body_width_mm <- number_of_samples * 6.2

pdf_width_inches <- 14
pdf_height_inches <- max(
  14,
  min(
    32,
    (heatmap_body_height_mm + 95) / 25.4
  )
)


# ==============================================================================
# 16. Create heatmap
# ==============================================================================

heatmap_color_function <- circlize::colorRamp2(
  c(-2, 0, 2),
  c("#2166AC", "white", "#B2182B")
)

heatmap_object <- ComplexHeatmap::Heatmap(
  zscore_matrix,
  name = "Row Z-score",
  col = heatmap_color_function,

  top_annotation = top_annotation,
  right_annotation = right_annotation,

  cluster_columns = FALSE,
  column_split = sample_metadata$combined_group,
  cluster_column_slices = FALSE,
  column_gap = grid::unit(1.2, "mm"),

  cluster_rows = hc_rows,
  row_dend_reorder = row_annotation_table$logFC,
  row_gap = grid::unit(0, "mm"),
  row_dend_width = grid::unit(18, "mm"),

  show_column_names = TRUE,
  column_names_side = "top",
  column_names_rot = 45,
  column_names_centered = TRUE,
  column_names_gp = grid::gpar(
    fontsize = 9,
    fontface = "bold"
  ),
  column_names_max_height = grid::unit(18, "mm"),

  show_row_names = TRUE,
  row_names_side = "right",
  row_names_gp = grid::gpar(fontsize = row_font_size),
  row_names_max_width =
    ComplexHeatmap::max_text_width(
      rownames(zscore_matrix),
      gp = grid::gpar(fontsize = row_font_size)
    ) + grid::unit(1.5, "mm"),

  row_title_gp = grid::gpar(
    fontsize = 8,
    fontface = "bold"
  ),

  na_col = "grey90",
  rect_gp = grid::gpar(col = NA),
  border = FALSE,
  use_raster = FALSE,

  width = grid::unit(heatmap_body_width_mm, "mm"),
  height = grid::unit(heatmap_body_height_mm, "mm"),

  column_title = heatmap_title,
  column_title_side = "top",
  column_title_gp = grid::gpar(
    fontsize = 12,
    fontface = "bold",
    lineheight = 1.12
  ),

  heatmap_legend_param = list(
    title = "Row Z-score",
    at = c(-2, -1, 0, 1, 2),
    legend_height = grid::unit(46, "mm")
  )
)


# ==============================================================================
# 17. Export TSV files
# ==============================================================================

readr::write_tsv(
  significant_interaction,
  selected_results_tsv,
  na = "NA"
)

readr::write_tsv(
  row_annotation_table,
  row_annotations_tsv,
  na = "NA"
)

zscore_output <- tibble::tibble(
  row_id = rownames(zscore_matrix)
) |>
  dplyr::bind_cols(
    tibble::as_tibble(
      as.data.frame(
        zscore_matrix,
        check.names = FALSE
      ),
      .name_repair = "minimal"
    )
  )

readr::write_tsv(
  zscore_output,
  zscore_matrix_tsv,
  na = "NA"
)

sample_order_output <- sample_metadata |>
  dplyr::transmute(
    sample_order = .data$sample_order,
    sample_ID = .data$sample_ID,
    sex = as.character(.data$sex),
    fmt_donor_group = as.character(.data$fmt_donor_group),
    combined_group = as.character(.data$combined_group)
  )

readr::write_tsv(
  sample_order_output,
  sample_order_tsv,
  na = "NA"
)

summary_table <- tibble::tibble(
  dataset_name = dataset_name,
  clustering_name = clustering_name,
  interaction_test_id = interaction_test_id,
  fdr_threshold = fdr_threshold,
  significant_cluster_gene_results = number_of_results,
  unique_genes = number_of_unique_genes,
  significant_clusters = paste(
    significant_cluster_ids,
    collapse = ", "
  ),
  number_of_significant_clusters = number_of_clusters,
  samples_displayed = number_of_samples,
  matrix_input = "sample-level TMM-normalized CPM from cluster DGEList objects",
  imputation_enabled = impute_missing_by_group_mean,
  imputation_method = if (isTRUE(impute_missing_by_group_mean)) {
    "mean CPM within Sex x FMT donor group before log2 transformation"
  } else {
    "none"
  },
  missing_values_before_imputation = number_missing_before_imputation,
  imputed_values = number_imputed_values,
  rows_with_imputation = number_rows_with_imputation,
  transformation = "log2(CPM + 1) -> row Z-score -> clip [-2, 2]",
  row_clustering_base_distance = row_clustering_base_distance,
  row_clustering_r_scale = row_clustering_r_scale,
  row_clustering_same_cluster_bonus = row_clustering_same_cluster_bonus,
  row_clustering_linkage_method = row_clustering_linkage_method,
  output_pdf = heatmap_pdf
)

readr::write_tsv(
  summary_table,
  summary_tsv,
  na = "NA"
)


# ==============================================================================
# 18. Save PDF
# ==============================================================================

message("\nWriting heatmap PDF:")
message(heatmap_pdf)
message(
  "PDF dimensions: ",
  round(pdf_width_inches, 2),
  " x ",
  round(pdf_height_inches, 2),
  " inches"
)

grDevices::pdf(
  file = heatmap_pdf,
  width = pdf_width_inches,
  height = pdf_height_inches,
  onefile = TRUE,
  useDingbats = FALSE
)

ComplexHeatmap::draw(
  heatmap_object,
  heatmap_legend_side = "right",
  annotation_legend_side = "right",
  merge_legends = TRUE,
  legend_grouping = "original",
  padding = grid::unit(
    c(3, 3, 3, 3),
    "mm"
  )
)

grDevices::dev.off()


# ==============================================================================
# 19. Validate outputs and report
# ==============================================================================

expected_output_files <- c(
  heatmap_pdf,
  selected_results_tsv,
  row_annotations_tsv,
  zscore_matrix_tsv,
  sample_order_tsv,
  summary_tsv
)

missing_output_files <- expected_output_files[
  !file.exists(expected_output_files)
]

if (length(missing_output_files) > 0L) {
  stop(
    "Missing output file(s):\n",
    paste(missing_output_files, collapse = "\n"),
    call. = FALSE
  )
}

empty_output_files <- expected_output_files[
  file.info(expected_output_files)$size == 0
]

if (length(empty_output_files) > 0L) {
  stop(
    "Empty output file(s):\n",
    paste(empty_output_files, collapse = "\n"),
    call. = FALSE
  )
}

message("\nHeatmap completed successfully.")
message("Output directory:")
message(normalizePath(heatmap_output_dir, mustWork = TRUE))
message("\nHeatmap PDF:")
message(normalizePath(heatmap_pdf, mustWork = TRUE))

